def solve_fixed():
    min_a = 100
    for s in range(20):
        N = 40 - s
        for k in range(s + 2, N + 1):
            max_n1 = N // k
            if max_n1 % 2 == 0:
                max_n1 -= 1

            for n1 in range(max_n1, 0, -2):
                nk = N - (k-1)*n1
                if nk % 2 == 1 and nk >= n1:
                    sum_sq = (k-1)*n1**2 + nk**2
                elif nk % 2 == 0 and nk - 2 >= n1:
                    sum_sq = (k-2)*n1**2 + (n1+2)**2 + (nk-2)**2
                else:
                    continue

                lower_bound = N - n1
                upper_bound = N + s - 1

                if s > 0:
                    # a(s-N) <= s^2 - s - N^2 + sum_sq
                    # Since s-N < 0, a >= (s^2 - s - N^2 + sum_sq) / (s-N)
                    lb_cond3 = math.ceil((s**2 - s - N**2 + sum_sq) / (s - N))
                    lower_bound = max(lower_bound, lb_cond3)

                    # aN <= sN + N^2 - sum_sq
                    ub_cond4 = math.floor((s*N + N**2 - sum_sq) / N)
                    upper_bound = min(upper_bound, ub_cond4)
                else:
                    # s=0: a = (N^2 - sum_sq) / N
                    if (N**2 - sum_sq) % N == 0:
                        a_val = (N**2 - sum_sq) // N
                        if N - n1 <= a_val <= N + s - 1 and a_val <= 39:
                            min_a = min(min_a, a_val)
                    continue

                if lower_bound <= upper_bound and lower_bound <= 39:
                    min_a = min(min_a, lower_bound)
    return min_a

import math
print(solve_fixed())

import math

def solve_comprehensive_fixed():
    min_a = 100
    for s in range(20):
        N = 40 - s
        for k in range(s + 2, N + 1):
            max_n1 = N // k
            if max_n1 % 2 == 0:
                max_n1 -= 1

            for n1 in range(max_n1, 0, -2):
                if (N - k*n1) % 2 == 0 and N >= k*n1:
                    Y = (N - k*n1) // 2
                    q = Y // k
                    r = Y % k
                    sum_sq_y_min = (k-r)*q**2 + r*(q+1)**2
                    current_sum_sq = k*n1**2 + 4*n1*Y + 4*sum_sq_y_min

                    lower_bound = N - n1
                    upper_bound = N + s - 1

                    if s > 0:
                        lb_cond3 = math.ceil((s**2 - s - N**2 + current_sum_sq) / (s - N))
                        lower_bound = max(lower_bound, lb_cond3)
                        ub_cond4 = math.floor((s*N + N**2 - current_sum_sq) / N)
                        upper_bound = min(upper_bound, ub_cond4)
                    else:
                        if (N**2 - current_sum_sq) % N == 0:
                            a_val = (N**2 - current_sum_sq) // N
                            if N - n1 <= a_val <= N + s - 1 and a_val <= 39:
                                min_a = min(min_a, a_val)
                        continue

                    if lower_bound <= upper_bound and lower_bound <= 39:
                        min_a = min(min_a, lower_bound)
    return min_a

print(solve_comprehensive_fixed())
